// estimate wall-clock time for a request to a region `distanceKm` away
function estimateLatencyMs({ distanceKm, payloadBytes, linkMbps, serialCalls }) {
  // time to push the bytes through the link
  const transferMs = (payloadBytes * 8) / (linkMbps * 1000);

  // signal travels at the speed of light
  const speedKmPerMs = 300000;
  const propagationMs = distanceKm / speedKmPerMs;

  // total: transfer + one trip there
  const perCall = transferMs + propagationMs;
  return perCall; // serialCalls dependent requests share this
}
